+__aicore__ inline
+uint32_t CeilDiv(uint32_t a, uint32_t b)
+{
+    return (a + b - 1) / b;
+}
+
+__aicore__ inline
+int64_t CeilDiv(int64_t a, int64_t b)
+{
+    return (a + b - 1) / b;
+}
+
+__aicore__ inline
+uint32_t RoundUp(uint32_t a, uint32_t b)
