+                        tokenNumPerHeadThisSubBlock,
+                        proTokenIdx, proTokenNum, integralHeadNum, epiTokenNum);
+                    AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID2);
+                    Arch::CrossCoreWaitFlag(qkReady);
