+        Add(updateExpSumVreg, updateExpSumVreg, brcExpSumFloatVreg, pregTailM);
+        StoreAlign<float, StoreDist::DIST_NORM_B32>(sumUb + mLoops * FLOAT_REP_SIZE, updateExpSumVreg, pregTailM);
+    }
+};
