+        const uint32_t blockCount = tla::get<1, 1>(srcTensor.shape());
+        const uint32_t blockLen = tla::get<0, 0>(srcTensor.shape()) * tla::get<0, 1>(srcTensor.shape());
+        const uint32_t dstOuterStrideCol = tla::get<1, 1>(dstTensor.stride());
