+                AscendC::PipeBarrier<PIPE_V>();
+            }
+            if (std::is_same<ElementO, bfloat16_t>::value) {
+                AscendC::Cast(
+                    goUbTensor16, goUbTensor32,
+                    AscendC::RoundMode::CAST_RINT,
