+struct CopyGmToL1<ArchTag, Gemm::GemmType<Element, layout::zN>> {
+    using LayoutDst = layout::zN;
+    using LayoutSrc = layout::zN;
+
+    static constexpr uint32_t ELE_NUM_PER_C0 = BYTE_PER_C0 / sizeof(Element);
+
+    // Methods
+
+    __aicore__ inline
