+        loadDataParams.mStartPosition = CeilDiv<C0_NUM_PER_FRACTAL>(tla::get<0>(srcCoord));
+        loadDataParams.kStartPosition = CeilDiv<ELE_NUM_PER_C0>(tla::get<1>(srcCoord));
+        loadDataParams.mStep = CeilDiv<C0_NUM_PER_FRACTAL>(L0K);
